// Copy the grouped object
const request = { ...$json.search_request };

// --------------------------------------------------
// Validate Query
// --------------------------------------------------
if (!request.query) {
	throw new Error("Query is required.");
}

if (typeof request.query !== "string") {
	throw new Error("Query must be a string.");
}

request.query = request.query.trim();

if (request.query.length === 0) {
	throw new Error("Query cannot be empty.");
}

// --------------------------------------------------
// Validate top_k
// --------------------------------------------------
if (
	request.top_k === undefined ||
	request.top_k === null ||
	request.top_k === ""
) {
	request.top_k = 10;
}

request.top_k = parseInt(request.top_k, 10);

if (isNaN(request.top_k) || request.top_k < 1) {
	throw new Error("top_k must be a positive integer.");
}

// Enterprise safety limit
if (request.top_k > 50) {
	request.top_k = 50;
}

// --------------------------------------------------
// Return same structure
// --------------------------------------------------
return {
	json: {
		search_request: request
	}
};

const request = { ...$json.search_request };

// Preserve original query
const originalQuery = request.query;

// Normalize query
let normalized = originalQuery;

// Remove control characters
normalized = normalized.replace(/[\u0000-\u001F\u007F]/g, " ");

// Replace tabs/newlines with spaces
normalized = normalized.replace(/\s+/g, " ");

// Trim
normalized = normalized.trim();

// Lowercase
normalized = normalized.toLowerCase();

// Store separately
request.normalized_query = normalized;

return {
  json: {
    search_request: request
  }
};

const request = { ...$json.search_request };

// ------------------------------
// Generate Metadata
// ------------------------------

const metadata = {
	//request_id: crypto.randomUUID(),
  request_id: `REQ-${Date.now()}-${Math.floor(Math.random() * 1000000)}`,

	workflow_name: "Knowledge Query Processing",

	workflow_version: "1.0",

	request_status: "validated",

	created_at: new Date().toISOString(),

	search_engine: "qdrant",

	embedding_provider: "gemini",

	embedding_model: "gemini-embedding-001"
};

// Return
return {
	json: {
		search_request: request,
		request_metadata: metadata
	}
};

// ==========================================
// Workflow 3 - Node 7
// Retrieval Post-Processor
// ==========================================

// Qdrant already returns results sorted by score.
// Create a copy instead of sorting again.
// Copy results returned by Qdrant
const points = [...($json.result?.points || [])];

// Ensure results are always sorted by similarity score (highest first)
// This keeps the workflow independent of the vector database implementation.
points.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));

// Build structured chunks
const chunks = points.map((point, index) => ({
    rank: index + 1,

    // Search Information
    score: point.score ?? 0,

    // IDs
    chunk_uuid: point.payload.chunk_uuid,
    chunk_id: point.payload.chunk_id,
    document_uuid: point.payload.document_uuid,
    document_hash: point.payload.document_hash,

    // Chunk Information
    chunk_index: point.payload.chunk_index,
    total_chunks: point.payload.total_chunks,
  chunk_start:point.payload.chunk_start,
  chunk_end:point.payload.chunk_end,
    text: point.payload.text,

    // Document Structure
    section_title: point.payload.section_title,
    section_level: point.payload.section_level,

    // Classification
    category: point.payload.category,
    department: point.payload.department,

    // File Information
    file_name: point.payload.file_name,
    file_extension: point.payload.file_extension,

    // Processing Metadata
    workflow_version: point.payload.workflow_version,
    processing_state: point.payload.processing_state,
    source: point.payload.source,
    received_at: point.payload.received_at
}));

// Create formatted context for the LLM
const formatted_context = chunks.map(chunk => `
### Result ${chunk.rank}
Similarity Score: ${(chunk.score ?? 0).toFixed(4)}

Document:
${chunk.file_name}

Section:
${chunk.section_title}

Content:
${chunk.text}
`.trim()).join('\n\n------------------------------------------------------------\n\n');

// Return standardized retrieval object
return [{
    json: {
      search_request: $json.search_request,
      request_metadata: $json.request_metadata,
        retrieval: {
            /**total_results: chunks.length,
            best_score: chunks.length ? chunks[0].score : 0,**/
            formatted_context,
            chunks
        },
      retrieval_metrics:$json.retrieval_metrics,
        search_status: $json.search_status,
        search_time: $json.search_time,
      retrieval_version: "1.0",
      retrieval_analytics: {

    documents_retrieved: new Set(
        chunks.map(c => c.document_uuid)
    ).size,

    highest_score: chunks.length
        ? Math.max(...chunks.map(c => c.score))
        : 0,

    lowest_score: chunks.length
        ? Math.min(...chunks.map(c => c.score))
        : 0,

    average_score: chunks.length
        ? Number(
            (
                chunks.reduce((sum, c) => sum + c.score, 0) /
                chunks.length
            ).toFixed(4)
        )
        : 0,

    duplicate_documents:
        chunks.length -
        new Set(chunks.map(c => c.document_uuid)).size
},
     retrieval_status :$json.retrieval_status 

    }
}];

// ==========================================
// Workflow 3 - Similarity Threshold Filter
// ==========================================

// Production default.
// Later replace with:
// const MIN_SCORE = parseFloat($env.QDRANT_MIN_SIMILARITY || "0.75");

const MIN_SCORE = 0.50;

// Get Qdrant results
const points = $json.result?.points || [];

// Apply threshold
const filteredPoints = points.filter(point =>
    (point.score ?? 0) >= MIN_SCORE
);

// ----------------------------
// Determine retrieval status
// ----------------------------

let retrievalStatus = "SUCCESS";
let retrievalReason = "Relevant documents found.";

if (points.length === 0) {
    retrievalStatus = "EMPTY_COLLECTION";
    retrievalReason = "Vector search returned no documents.";
}
else if (filteredPoints.length === 0) {
    retrievalStatus = "NO_MATCH";
    retrievalReason = "No documents satisfied the similarity threshold.";
}

// Return standardized output
return [{
    json: {

             search_request:$json.search_request,
      request_metadata: $json.request_metadata,


        result: {
            points: filteredPoints
        },

        retrieval_status: {
            status: retrievalStatus,
            reason: retrievalReason
        },

        retrieval_metrics: {
            threshold: MIN_SCORE,
            total_results: points.length,
            filtered_results: filteredPoints.length,
            discarded_results: points.length - filteredPoints.length,
            best_score: filteredPoints.length
                ? filteredPoints[0].score
                : 0
        },

        search_status: $json.status,
        search_time: $json.time
    }
}];
